    if publishErrno == EEXIST {
        writeStderr("error: snapshot already exists: \(snapshotPath)\n")
        return 73
    }
    writeStderr("error: cannot publish snapshot to \(snapshotPath): "
        + String(cString: strerror(publishErrno)) + "\n")
    return 74
}

