58	    let rootURL = URL(fileURLWithPath: root)
59	    var enumerationErrors: [CompareError] = []
60	    guard let enumerator = FileManager.default.enumerator(
61	        at: rootURL,
62	        includingPropertiesForKeys: Array(keys),
63	        options: [],
64	        errorHandler: { url, error in
