107	/// Hashes one regular file, verifying it stays a regular file with unchanged
108	/// size and modification time across the read.
109	func hashFile(root: String, relativePath: String) -> Result<FileRecord, CompareError> {
110	    let fullPath = root == "/" ? "/" + relativePath : root + "/" + relativePath
111	
112	    var before = stat()
113	    guard lstat(fullPath, &before) == 0 else {
114	        return .failure(CompareError(
115	            path: relativePath,
116	            message: "cannot stat: \(String(cString: strerror(errno)))"))
117	    }
118	    guard isRegularFile(before) else {
119	        return .failure(CompareError(path: relativePath, message: "not a regular file"))
120	    }
121	    guard let handle = FileHandle(forReadingAtPath: fullPath) else {
122	        return .failure(CompareError(path: relativePath, message: "cannot open for reading"))
123	    }
124	    defer { try? handle.close() }
125	
126	    var hasher = SHA256()
127	    while true {
128	        let chunk: Data
129	        do {
130	            chunk = try handle.read(upToCount: 1 << 20) ?? Data()
131	        } catch {
132	            return .failure(CompareError(
133	                path: relativePath,
134	                message: "read failed: \(error.localizedDescription)"))
135	        }
136	        if chunk.isEmpty { break }
137	        hasher.update(data: chunk)
138	    }
139	
140	    var after = stat()
141	    guard lstat(fullPath, &after) == 0 else {
142	        return .failure(CompareError(path: relativePath, message: "vanished while reading"))
143	    }
144	    guard isRegularFile(after),
145	          after.st_size == before.st_size,
146	          sameModificationTime(after, before)
147	    else {
148	        return .failure(CompareError(path: relativePath, message: "changed while reading"))
149	    }
150	
151	    let hex = hasher.finalize().map { String(format: "%02x", $0) }.joined()
152	    return .success(FileRecord(path: relativePath, sha256: hex, size: before.st_size))
153	}
