5	/// A minimal RFC 8259 parser. It is deliberately stricter than
6	/// JSONSerialization: duplicate object keys, trailing content, unpaired
7	/// surrogates and control characters inside strings are all rejected, and
8	/// number spelling is preserved so integer/float distinctions survive.
9	private enum JSONValue {
10	    case null
11	    case bool(Bool)
12	    /// Token matching `-?(0|[1-9][0-9]*)`.
13	    case integer(String)
14	    /// Any other valid JSON number spelling.
15	    case number(String)
16	    case string(String)
17	    case array([JSONValue])
18	    case object([(key: String, value: JSONValue)])
19	}
