25	private struct JSONParser {
26	    let bytes: [UInt8]
27	    var index = 0
28	
29	    static func parse(_ data: Data) throws -> JSONValue {
30	        var parser = JSONParser(bytes: Array(data))
31	        let value = try parser.parseValue()
32	        parser.skipWhitespace()
33	        guard parser.index == parser.bytes.count else {
34	            throw JSONParseError(message: "trailing content after JSON value")
35	        }
36	        return value
37	    }
