43	    private mutating func skipWhitespace() {
44	        while index < bytes.count {
45	            switch bytes[index] {
46	            case 0x20, 0x09, 0x0A, 0x0D:
47	                index += 1
48	            default:
49	                return
50	            }
51	        }
52	    }
